import{_ as a,o,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Instalação","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/install.md","filePath":"pt-BR/guide/install.md"}'),t={name:"pt-BR/guide/install.md"};function r(n,e,d,l,c,p){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="instalacao" tabindex="-1">Instalação <a class="header-anchor" href="#instalacao" aria-label="Permalink to &quot;Instalação&quot;">​</a></h1><p>De um servidor limpo até uma aplicação respondendo em HTTPS.</p><h2 id="requirements" tabindex="-1">Requisitos <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requisitos {#requirements}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sistema</th><th>Arquitetura</th><th>Como é verificado</th></tr></thead><tbody><tr><td>Ubuntu 26.04</td><td>x86_64</td><td>Conferido à mão numa VPS de referência; o instalador também roda num contêiner Ubuntu 26.04</td></tr><tr><td>Ubuntu 24.04</td><td>x86_64, arm64</td><td>Instalações reais em testes automatizados, incluindo uma interrupção e a retomada</td></tr><tr><td>Ubuntu 22.04</td><td>x86_64</td><td>Instalações reais em testes automatizados, como acima</td></tr><tr><td>Ubuntu 22.04</td><td>arm64</td><td>Declarado; conferido só à mão</td></tr><tr><td>Debian 12</td><td>x86_64, arm64</td><td>Declarado; conferido só à mão</td></tr></tbody></table><p>As verificações do Orbit recusam qualquer outro. O servidor também precisa de:</p><ul><li>2 vCPUs, 2 GB de memória e 20 GB livres em <code>/var/lib</code>. 4 GB é melhor se você fizer build de aplicações Next.js ou Nuxt nele.</li><li>Root por SSH, relógio sincronizado e DNS funcionando.</li><li>HTTPS de saída para github.com, release-assets.githubusercontent.com e quay.io.</li><li>Portas 80, 443 e 6443 livres. Não use uma imagem com painel de controle ou servidor web.</li><li>Se o seu provedor tiver firewall, libere 22, 80 e 443. Deixe 6443 e 7443 fechadas para a internet; abra-as só para os <a href="./servers">servidores que você adicionar depois</a>.</li><li>Alguns provedores dão ao servidor só um endereço da rede interna deles e ligam um público a ele: Oracle Cloud, AWS, Google Cloud e Azure. O Orbit percebe isso, pergunta o endereço público para checkip.amazonaws.com ou api.ipify.org e usa esse no console, nos endereços gerados e nos registros de DNS. Na Oracle Cloud, as portas 80 e 443 se abrem na security list da sub-rede.</li></ul><h2 id="installer" tabindex="-1">Rodando o instalador <a class="header-anchor" href="#installer" aria-label="Permalink to &quot;Rodando o instalador {#installer}&quot;">​</a></h2><p>No servidor:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/getcortexlabs/orbit-releases/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span></span></code></pre></div><p>O instalador:</p><ol><li>confere que roda como root num Linux com systemd, em x86_64 ou arm64;</li><li>baixa o Orbit para a arquitetura do servidor a partir das <a href="https://github.com/getcortexlabs/orbit-releases/releases" target="_blank" rel="noreferrer">versões publicadas</a> e recusa um arquivo cujo SHA-256 não confere (<code>ORBIT_VERSION=0.1.27</code> fixa uma versão);</li><li>inicia o serviço e verifica a máquina. Se uma verificação bloquear, ele para antes de mudar qualquer coisa e diz como resolver;</li><li>instala K3s, Traefik, cert-manager, BuildKit e o agente do Orbit, em uns cinco minutos;</li><li>termina com o endereço do console e um token de uso único:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Orbit is ready.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Console  https://orbit.203-0-113-10.sslip.io</span></span>
<span class="line"><span>  Token    boot-7KQ2-MX9P-4TRW</span></span></code></pre></div><p>Rodar o mesmo comando de novo retoma uma instalação interrompida ou atualiza o Orbit.</p><p>Se uma versão anterior publicou o console num endereço como <code>orbit.10-0-0-5.sslip.io</code>, a atualização leva o console e todos os endereços gerados para o endereço público. O <code>orbit status</code> mostra o novo.</p><h2 id="first-steps" tabindex="-1">Primeiros passos <a class="header-anchor" href="#first-steps" aria-label="Permalink to &quot;Primeiros passos {#first-steps}&quot;">​</a></h2><ol><li><strong>Abra o console.</strong> Abra o endereço e crie o administrador com o token. O certificado vem do Let&#39;s Encrypt, então o servidor precisa estar acessível na porta 80.</li><li><strong>Conecte o GitHub</strong> (opcional). Em Novo projeto, escolha Conectar o GitHub. O GitHub cria um App para este Orbit e pergunta onde instalá-lo e quais repositórios ele pode ler. Veja <a href="./github">GitHub e previews</a>. Para fazer build a partir do GitLab ou do Bitbucket, conecte-o em Configurações → Integrações com um token de acesso; veja <a href="./gitlab">GitLab</a> e <a href="./bitbucket">Bitbucket</a>.</li><li><strong>Publique.</strong> Crie um projeto a partir de um repositório ou de uma imagem de contêiner. O Orbit faz o build no servidor, dá a ele um endereço HTTPS e confere que ele responde.</li><li><strong>Adicione um banco de dados</strong> ao projeto e conecte-o: a aplicação recebe <code>DATABASE_URL</code> nas suas variáveis.</li><li><strong>Configure os backups</strong> para um armazenamento externo, para que seus dados sobrevivam à perda do servidor. Veja <a href="./backups">Backups e recuperação</a>.</li></ol><h2 id="console-address" tabindex="-1">O endereço do console <a class="header-anchor" href="#console-address" aria-label="Permalink to &quot;O endereço do console {#console-address}&quot;">​</a></h2><p>O console começa em <code>https://orbit.&lt;ip-do-servidor-com-hifens&gt;.sslip.io</code>. O sslip.io é um serviço público de DNS que resolve qualquer nome com um IP para esse IP, então o Orbit consegue um certificado no primeiro minuto sem um domínio seu. Para usar o seu, como <code>orbit.exemplo.com</code>, digite-o em <strong>Endereço do console</strong> durante a instalação, ou depois em <strong>Configurações → Endereço do console</strong>:</p><ol><li>Crie o registro que o Orbit mostra: um registro <code>A</code> apontando para o endereço público do servidor, ou um por servidor de entrada quando há vários. Com o <a href="./cloudflare">DNS da Cloudflare conectado</a> e o hostname numa das suas zonas, o Orbit cria o registro.</li><li>O Orbit confere o DNS a cada 30 segundos, como faz com os domínios das aplicações, e avisa quando o registro falta ou aponta para outro lugar.</li><li>Quando ele aponta para cá, o Let&#39;s Encrypt assina um certificado, e o hostname vira o endereço do console: os links das notificações e o webhook do App do GitHub passam para lá, e os webhooks do GitLab e do Bitbucket criados a partir daí usam esse endereço.</li></ol><p>O endereço sslip.io continua respondendo o tempo todo, então um erro de digitação ou um DNS demorado nunca deixa você do lado de fora. Quando o novo endereço tem certificado, <strong>Continuar respondendo em</strong> desliga o endereço sslip.io; um hostname vazio volta para ele. Enquanto um servidor roda o <a href="./tunnel#console">Cloudflare Tunnel</a>, o hostname é publicado pelo tunnel, com um <code>CNAME</code> com proxy.</p><h2 id="what-it-adds" tabindex="-1">O que a instalação adiciona <a class="header-anchor" href="#what-it-adds" aria-label="Permalink to &quot;O que a instalação adiciona {#what-it-adds}&quot;">​</a></h2><p>Estes serviços sobem com o servidor:</p><ul><li><code>orbit.service</code>, o plano de controle;</li><li><code>k3s.service</code>, o Kubernetes;</li><li><code>orbit-firewall.service</code>, que deixa as portas 6443 e 8080 acessíveis só pela própria máquina e pelos seus workloads;</li><li><code>orbit-agent.service</code>, que informa a saúde do servidor ao Orbit;</li><li><code>orbit-buildkit.service</code>, que faz o build dos seus repositórios.</li></ul><p>O Orbit guarda seus dados em <code>/var/lib/orbit</code> e a identidade do agente em <code>/var/lib/orbit-agent</code>.</p><h2 id="by-hand" tabindex="-1">Instalando à mão <a class="header-anchor" href="#by-hand" aria-label="Permalink to &quot;Instalando à mão {#by-hand}&quot;">​</a></h2><ol><li><p>Baixe <code>orbit-linux-&lt;arch&gt;.tar.gz</code> das <a href="https://github.com/getcortexlabs/orbit-releases/releases" target="_blank" rel="noreferrer">versões publicadas</a>. Ele traz o <code>orbit</code> (com o console dentro), o <code>orbit-agent</code> e o <code>orbit.service</code>.</p></li><li><p>Copie para o servidor e inicie o serviço:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit.service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@SERVIDOR:/tmp/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@SERVIDOR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;install -m 0755 /tmp/orbit /tmp/orbit-agent /usr/local/bin/ \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &amp;&amp; install -m 0644 /tmp/orbit.service /etc/systemd/system/ \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &amp;&amp; systemctl daemon-reload &amp;&amp; systemctl enable --now orbit&#39;</span></span></code></pre></div></li><li><p>Pegue o token de uso único para criar o administrador. Ele funciona uma vez e expira em uma hora:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@SERVIDOR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap-token</span></span></code></pre></div></li><li><p>Até o runtime ser instalado, o console só escuta em <code>127.0.0.1:8080</code>. Abra-o por um túnel SSH e acesse <a href="http://127.0.0.1:8080" target="_blank" rel="noreferrer">http://127.0.0.1:8080</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:127.0.0.1:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@SERVIDOR</span></span></code></pre></div></li><li><p>Crie o administrador e siga as verificações, o plano e a instalação no console, ou rode <code>sudo orbit install</code> no servidor.</p></li><li><p>Até um minuto depois da instalação, o console é publicado em <code>https://orbit.&lt;ip-do-servidor-com-traços&gt;.sslip.io</code> (o <code>orbit status</code> mostra o endereço), com um certificado do Let&#39;s Encrypt. O túnel continua funcionando.</p></li></ol>`,26)])])}const m=a(t,[["render",r]]);export{h as __pageData,m as default};
